// ===== p275 : chaque fiche a la voix de celui qui la tient — et se lit facilement.
// Le gouverneur et l'administration : une écriture de bureau nette (les polices de Microsoft : Segoe UI, Calibri, sinon celle du système) ;
// les rois, gouverneurs et nobles : en petites capitales ; les marrons : une main simple et lisible (Patrick Hand) ;
// les chasseurs de marrons et les petits colons : une impression rustique de campagne française (IM Fell English) ;
// les femmes : la Lucida Handwriting de Windows, sinon Dancing Script ; le curé et l'Église : un vieil italique de livre de messe (IM Fell DW Pica) ;
// les engagés indiens : Kalam (dessinée pour l'Inde) ; le mythe et la mystique : Uncial Antiqua ; le reste, les archives : Alegreya.
// La note « dans l'histoire réelle » garde l'écriture ordinaire, pour qu'on sache toujours ce qui est vrai. Polices libres (SIL OFL), intégrées. =====
const CSS275="@font-face{font-family:'Patrick Hand';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'IM Fell English';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Dancing Script';font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'IM Fell DW Pica';font-style:italic;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}";
{const st=document.createElement('style');st.id='polices275';st.textContent=CSS275+
 '.carte[data-voix] p:not(.vrai):not(.note){line-height:1.5}'+
 '.carte[data-voix=admin] p:not(.vrai),.plume208.admin,.v275admin{font-family:"Segoe UI",Calibri,Candara,"Trebuchet MS",system-ui,sans-serif!important;font-size:16px!important;letter-spacing:.005em}'+
 '.carte[data-voix=marron] p:not(.vrai),.plume208.marron,.v275marron{font-family:"Patrick Hand",Kalam,system-ui,sans-serif!important;font-size:19px!important;font-weight:400}'+
 '.carte[data-voix=paysan] p:not(.vrai),.plume208.paysan,.v275paysan{font-family:"IM Fell English",Georgia,serif!important;font-size:18px!important}'+
 '.carte[data-voix=dame] p:not(.vrai),.plume208.dame,.v275dame{font-family:"Lucida Handwriting","Lucida Calligraphy","Dancing Script",cursive!important;font-size:17px!important;line-height:1.6}'+
 '.carte[data-voix=reli] p:not(.vrai),.plume208.reli,.v275reli{font-family:"IM Fell DW Pica",Georgia,serif!important;font-style:italic;font-size:18px!important}'+
 '.carte[data-voix=inde] p:not(.vrai),.plume208.inde,.v275inde{font-family:Kalam,system-ui,sans-serif!important;font-size:17px!important}'+
 '.carte[data-voix=myst] p:not(.vrai),.plume208.mystique,.v275myst{font-family:"Uncial Antiqua",Alegreya,serif!important;font-size:16px!important;line-height:1.6}'+
 '.carte[data-noble] h2,.carte[data-noble] p:not(.vrai),.plume208.noble,.v275noble{font-variant:small-caps;letter-spacing:.04em}'+
 '.plume208{font-family:Alegreya,Georgia,serif;font-size:17px!important!important;line-height:1.55!important}';
 document.head.appendChild(st)}
// qui parle ? d'abord le titre, puis le début du texte
const RX275={
 admin:/gouverneur|compagnie des indes|la compagnie|ordonnance|conseil (provincial|supérieur)|lettres patentes|\bédit\b|décret|commandant|intendant|préfet|administration|règlement|assemblée coloniale|recensement|arrêté/i,
 noble:/\broi\b|\breine\b|\bcomte\b|marquis|baron|\bduc\b|noble|la bourdonnais|bonaparte|napoléon|louis xv|sa majesté/i,
 reli:/curé|prêtre|abbé|église|chapelle|\bmesse\b|lazarist|évêque|baptê|pèlerin|vierge|religieu|paroisse|sermon|catéchisme/i,
 paysan:/détachement|chasseurs? de marrons|chasseurs?\b|mussard|milice|fusilleur|battue|bronchard|capture|petits? blancs?|petit colon|habitant des hauts/i,
 dame:/\b(dame|madame|demoiselle|femme|femmes|sœur|sœurs|veuve|héva|sarlave|raharianne|simangavole|simangalove|marianne|delphine|mère|grand-mère|sage-femme)\b/i,
 inde:/engagé|tamoul|malbar|kovil|indien|pondichéry|karikal|marche sur le feu|cavadee|cavadi/i,
 marron:/marron|camp\b|camps\b|esclav|fuyard|kabar|ombiasy|fugitif|dans les hauts/i};
function voix275(e,id){const g=k=>{try{return e[k]}catch(x){return ''}};const tag=String(g('tag')||''),t=String(g('t')||''),b=String(g('b')||'').slice(0,260),tb=t+' '+b;
 let v='';if(RX275.admin.test(t))v='admin';
 else if(RX275.reli.test(t))v='reli';
 else if(/Mythe|Conte|Imaginaire|Mystique|Réalisme fantastique|Utopie/.test(tag))v='myst';
 else if(RX275.admin.test(b)&&!RX275.marron.test(t))v='admin';
 else if(RX275.paysan.test(t)||(S&&S.voieC&&RX275.paysan.test(b)))v='paysan';
 else if(RX275.dame.test(t))v='dame';
 else if(RX275.inde.test(tb))v='inde';
 else if(tag==='Mémoire'||RX275.marron.test(tb))v='marron';
 else if(RX275.reli.test(b))v='reli';
 return {v,noble:RX275.noble.test(t)||(v==='admin'&&RX275.noble.test(b.slice(0,140)))}}
{const md=modal;modal=function(){const r=md.apply(this,arguments);try{const m=$('modal'),c=m&&m.querySelector('.carte');if(c&&S&&S.evq&&S.evq.length){const id=S.evq[0],e=EV[id];if(e){const o=voix275(e,id);if(o.v)c.dataset.voix=o.v;else delete c.dataset.voix;if(o.noble)c.dataset.noble=1;else delete c.dataset.noble}}}catch(x){}return r}}
// les « Fiches de l'île » prennent les mêmes voix
if(typeof main208==='function'){main208=function(f){const o=voix275({tag:f.tag,t:f.t,b:f.b});return ({myst:'mystique'}[o.v]||o.v)+(o.noble?' noble':'')}}
// le songe du gouverneur : écriture de bureau, titres en capitales ; le songe du curé : l'italique du livre de messe
setInterval(()=>{try{const g=document.getElementById('gouv273');if(g&&!g.dataset.v275){g.dataset.v275=1}if(g)g.querySelectorAll('p').forEach(p=>{if(!p.classList.contains('v275admin')&&!/réels/.test(p.textContent))p.classList.add('v275admin')});if(g)g.querySelectorAll('h2').forEach(h=>h.classList.add('v275noble'));
 const s=document.getElementById('songe272');if(s)s.querySelectorAll('.carte p').forEach(p=>p.classList.add('v275reli'))}catch(e){}},200);
